foreach ($m in $list) {
  $f = Join-Path "mods" $m[0]
  if ((Test-Path -LiteralPath $f) -and ((Get-FileHash -LiteralPath $f -Algorithm SHA1).Hash.ToLower() -eq $m[2])) { Write-Host "ok  $($m[0])"; continue }
  try { Invoke-WebRequest -Uri $m[1] -OutFile $f -UseBasicParsing } catch { Write-Host "ERRO download $($m[0])"; $fail = $true; continue }
  if ((Get-FileHash -LiteralPath $f -Algorithm SHA1).Hash.ToLower() -eq $m[2]) { Write-Host "baixado $($m[0])" } else { Write-Host "ERRO hash $($m[0])"; $fail = $true }
}
if ($fail) { Write-Host "Houve erros, veja acima."; exit 1 } else { Write-Host "Pronto: todos os mods conferidos." }
